#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package WolverineFx@4.2.0 #:package WolverineFx.Marten@4.2.0 #:package WolverineFx.RDBMS@4.2.0 #:package WolverineFx.Postgresql@4.2.0 #:package WolverineFx.FluentValidation@4.2.0 #:package WolverineFx.Http@4.2.0 #:package WolverineFx.RabbitMQ@4.2.0 #:package WolverineFx.AzureServiceBus@4.2.0 #:package WolverineFx.Http.FluentValidation@4.2.0 #:package WolverineFx.Http.Marten@4.2.0 #:package WolverineFx.AmazonSqs@4.2.0 #:package WolverineFx.EntityFrameworkCore@4.2.0 #:package WolverineFx.SqlServer@4.2.0 #:package WolverineFx.Kafka@4.2.0 #:package WolverineFx.MemoryPack@4.2.0 #:package WolverineFx.MessagePack@4.2.0 #:package WolverineFx.MQTT@4.2.0 #:package WolverineFx.Pubsub@4.2.0 #:package WolverineFx.Pulsar@4.2.0 #:package WolverineFx.RavenDb@4.2.0 #:package Microsoft.CodeAnalysis.Common@4.14.0 #:package Microsoft.CodeAnalysis.Workspaces.Common@4.14.0 #:package Swashbuckle.AspNetCore@9.0.3 #:package Swashbuckle.AspNetCore.Swagger@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerGen@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerUI@9.0.3 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property GenerateJsonSourceGeneration=true  using Microsoft.AspNetCore.Builder; using Microsoft.Extensions.DependencyInjection; using Wolverine; using Contracts.Messages;  var builder = WebApplication.CreateBuilder(args); builder.Logging.AddConsole(); // 同样使用默认 InMemoryTransport，或者共用外部 transport builder.Host.UseWolverine(opts => {     // 如果组件 A 与 B 分别在不同进程，而你使用 RabbitMQ：     // opts.UseRabbitMq("amqp://guest:guest@localhost:5672");     // 如果你想把事件持久化到数据库（Outbox），打开下面的配置     // opts.PersistMessagesWithPostgres("Host=...;Database=...;Username=...;Password=...");     // opts.Policies.OnException<DbUpdateException>(e => e.Retry(3));     // opts.DefaultRoutingConvention = new Wolverine.RabbitMq.Routing.RabbitMqRoutingConvention();     // opts.UseRabbitMq(rabbit =>     // {     //     rabbit.ConnectionFactory.Uri = new Uri("amqp://guest:guest@localhost:5672");     //     rabbit.HostName = "localhost";     //     rabbit.Port = 5672;     //     rabbit.Username = "guest";     //     rabbit.Password = "guest";     // })ConfigureDeadLetterQueue("dead-letter");     // 开启 Outbox（即使 InMemory，也可以演示事务）     opts.EnableOutbox();   // 若使用真实DB 记得打开      // 让所有 Handler 自动发现（包括跨程序集）     opts.IncludeAssembly(typeof(IUserDeviceRepository).Assembly); // 自己的      //  Grafana/Prometheus、Jaeger 集成，监控每一步延迟、Saga 成功率.     opts.EnableOpenTelemetry(); }); builder.Services.AddSingleton<IUserRepository, InMemoryUserRepository>(); builder.Services.AddSingleton<IUserService, UserService>();  var app = builder.Build();  app.MapPost("/user/create", async (UserDto dto,     IUserService svc, IMessageBus bus) => {     var userId = await svc.CreateAsync(dto.Name);     await bus.PublishAsync(new UserCreated(userId, dto.Name, DateTimeOffset.UtcNow));     return Results.Created($"/user/{userId}", new { userId }); });  app.Run();  public record UserDto(string Name);  public interface IUserRepository {     Task<Guid> AddAsync(string name);     Task<User> GetAsync(Guid id); }  public class InMemoryUserRepository : IUserRepository {     private readonly ConcurrentDictionary<Guid, User> _store = new();     public Task<Guid> AddAsync(string name)     {         var id = Guid.NewGuid();         _store[id] = new User { Id = id, Name = name };         return Task.FromResult(id);     }     public Task<User> GetAsync(Guid id) => Task.FromResult(_store[id]); }  public class User {     public Guid Id { get; set; }     public string Name { get; set; } = default!; }  public interface IUserService {     Task<Guid> CreateAsync(string name); }  public class UserService : IUserService {     private readonly IUserRepository _repo;     public UserService(IUserRepository repo) => _repo = repo;     public Task<Guid> CreateAsync(string name) => _repo.AddAsync(name); }  public class UserHandler {     private readonly IUserRepository _repo;     public UserHandler(IUserRepository repo) => _repo = repo;      // 查询用户是否存在（BFF 的 “UserChecked” 步骤会用到）     public async Task<UserExistsResponse> Handle(UserExistsQuery query)     {         var user = await _repo.GetAsync(query.UserId);         return new UserExistsResponse(query.UserId, user != null);     } }
